parameters.jsCode:
const raw = $input.item.json.candidates[0].content.parts[0].text;
const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
const blog = JSON.parse(cleaned);

// blog.tags arrives as a pre-quoted string like: "tag1","tag2","tag3"
const tagsArray = JSON.parse('[' + blog.tags + ']');

// Build a search query for Unsplash - bias it toward real estate imagery
const searchQuery = 'Dubai real estate ' + tagsArray[0];

return [{
  json: {
    title: blog.title,
    excerpt: blog.excerpt,
    readTime: blog.readTime,
    body: blog.body,
    tags: tagsArray,
    searchQuery: searchQuery
  }
}];

parameters.jsonBody:
={{ (() => {
const blog = $('Parse Blog JSON').item.json;
const photo = $json.results && $json.results[0];
const uniqueId = 'drafts.' + Date.now() + '-' + Math.random().toString(36).substring(2, 8);

return JSON.stringify({
  mutations: [{
    create: {
      _id: uniqueId,
      _type: 'blog',
      title: blog.title,
      excerpt: blog.excerpt,
      readTime: blog.readTime,
      slug: { _type: 'slug', current: blog.title },
      body: blog.body,
      tags: blog.tags,
      coverImageUrl: photo ? photo.urls.regular : null,
      coverImageCredit: photo ? ('Photo by ' + photo.user.name + ' on Unsplash') : null
    }
  }]
});
})() }}
